/**
 * @method
 * @name scwin.selectStockDutyExer
 * @author Inswave
 * @date 2026. 09. 29
 * @param ipt_bzProcsNo ipt_prtdepoId
 * @returns
 * @hidden N
*/
scwin.selectStockDutyExer = function (ipt_bzProcsNo, ipt_prtdepoId) {
    /* sdd-asis-lifecycle:begin fn_selectStockDutyExer — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    let addHtml = "";
    scwin.exerShrs = 0;
    scwin.stockExerTbody.setLabel("");
    for (let i = 0; i < scwin.stockDutyExerarr.length; i++) {
        if (ipt_bzProcsNo === scwin.stockDutyExerarr[i].bzProcsNo && ipt_prtdepoId === scwin.stockDutyExerarr[i].prtdepoId && scwin.stockDutyExerarr[i].stkoptDutyExerPayDd !== "") {
            addHtml += '<tr><td class="td_board" align="right">' + scwin.dateFormat(scwin.stockDutyExerarr[i].stkoptDutyExerPayDd) + '</td>' + '<td class="td_board" align="right">' + $c.num.formatNumber(scwin.stockDutyExerarr[i].stkoptDutyExerShrs) + '</td>' + '<td class="td_board" align="right"></td></tr>';
            scwin.exerShrs += parseInt(scwin.stockDutyExerarr[i].stkoptDutyExerShrs);
        }
    }
    if (addHtml === "") {
        addHtml += '<tr><td colspan="4" class="td_board_2" >조회내용이 없습니다.</td></tr>';
    }
    $("#stockExerTbody").append(addHtml);
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.validate
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.validate = async function () {
    /* sdd-asis-lifecycle:begin fn_validate — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    let inserShrs = 0;
    for (let i = 0; i < $("input[name=stkoptDutyExerShrs]").length; i++) {
        inserShrs += parseInt($("input[name=stkoptDutyExerShrs]").eq(i).val());
    }
    if (parseInt(scwin.exerShrs) + parseInt(inserShrs) > parseInt(scwin.resultShrs)) {
        await $c.win.alert("총 부여주식수보다 행사주식수의 합이 많습니다.");
        return false;
    }
    let ddCnt = 0;
    /* 수동 전환 필요: 이름 선택자 순회 [name=stkoptDutyExerPayDd] — B4 반복 밖 동명 입력(정적/계수 틀) · to-be 에 돌 요소가 없다 */ $("input[name=cal_stkoptDutyExerPayDd]").each(async function(index, item) {
            if ($(item).val() === "") {
                await $c.win.alert("납입일을 입력해 하세요.");
                ddCnt++;
                return false;
            }
    });
    if (ddCnt != 0) {
        return false;
    }
    let shrsCnt = 0;
    /* 수동 전환 필요: 이름 선택자 순회 [name=stkoptDutyExerShrs] — B4 반복 밖 동명 입력(정적/계수 틀) · to-be 에 돌 요소가 없다 */ $("input[name=stkoptDutyExerShrs]").each(async function(index, item) {
            if ($(item).val() === "") {
                await $c.win.alert("행사주식수를 입력해 하세요.");
                shrsCnt++;
                return false;
            }
    });
    if (shrsCnt != 0) {
        return false;
    }
    return true;
    /* sdd-asis-lifecycle:end */
};


